package com.pratik.imagetap;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Recovery72Test {
 List<TapService> services=new ArrayList<>();Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("config",0).edit().putBoolean("reduceMotion",true).commit();}
 @After public void cleanup(){for(TapService s:services){s.stopSession("test");s.onDestroy();}TapService.instance=null;}
 TapService service()throws Exception{TapService s=Robolectric.buildService(TapService.class).create().get();services.add(s);set(s,"prefs",s.getSharedPreferences("config",0));set(s,"wm",s.getSystemService(Context.WINDOW_SERVICE));set(s,"visionReady",true);TapService.instance=s;return s;}
 static Object get(Object s,String n)throws Exception{return SessionPresetTest.get(s,n);}static void set(Object s,String n,Object v)throws Exception{SessionPresetTest.set(s,n,v);}
 static Object call(TapService s,String n,boolean b)throws Exception{Method m=TapService.class.getDeclaredMethod(n,boolean.class);m.setAccessible(true);return m.invoke(s,b);}
 TimedAction step(long delay){TimedAction a=TimedAction.create(ActionType.TAP);return new TimedAction(a.id,"step",a.action,a.x,a.y,a.endX,a.endY,delay,a.duration,true);}
 @Test public void repeatedConnectionDoesNotRestartRunningSession()throws Exception{TapService s=service();assertTrue(s.startSession());set(s,"taps",27L);Object panel=get(s,"panel");int generation=(Integer)get(s,"generation");s.onServiceConnected();assertEquals(27L,get(s,"taps"));assertSame(panel,get(s,"panel"));assertEquals(generation,get(s,"generation"));}
 @Test public void abruptLossRetainsCountLatchesPauseAndPosition()throws Exception{Bitmap b=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);File f=TargetStore.save(c,b);b.recycle();TapService old=service();old.startSession();set(old,"taps",23L);((boolean[])get(old,"latched"))[0]=true;((SessionPause)get(old,"pause")).manual=true;View panel=(View)get(old,"panel");WindowManager.LayoutParams p=(WindowManager.LayoutParams)panel.getLayoutParams();p.x=30;p.y=120;SessionPresetTest.invoke(old,"savePanelPosition");assertEquals(true,call(old,"checkpoint",true));TapService replacement=service();assertEquals(true,call(replacement,"startSession",true));assertEquals(23L,get(replacement,"taps"));assertTrue(((boolean[])get(replacement,"latched"))[0]);assertTrue(((SessionPause)get(replacement,"pause")).manual);WindowManager.LayoutParams restored=(WindowManager.LayoutParams)((View)get(replacement,"panel")).getLayoutParams();assertEquals(30,restored.x);assertEquals(120,restored.y);assertTrue(f.exists());}
 @Test public void timelineRecoveryRetainsStepAndDoesNotCountDowntime()throws Exception{AutomationClock clock=new AutomationClock(Arrays.asList(step(1000),step(3000)),true,false,100);clock.take(1100);clock.complete(1200);String saved=new SessionCheckpoint("timeline",1,0,false,false,Collections.emptySet(),clock).encode(1700);SessionCheckpoint restored=SessionCheckpoint.decode(saved,100000);assertEquals(1,restored.clock.index);assertEquals(2500,restored.clock.remaining(100000));assertEquals(-1,restored.clock.take(102499));assertEquals(1,restored.clock.take(102500));}
 @Test public void timedServiceRecoveryUsesRunningPlanNotLaterEditedPlan()throws Exception{AutomationStore.save(c,true,Arrays.asList(step(1000),step(3000)));c.getSharedPreferences("config",0).edit().putString("runMode","timeline").commit();TapService old=service();old.startSession();AutomationClock clock=(AutomationClock)get(old,"automation");long now=SystemClock.elapsedRealtime();clock.resume(now);clock.due[0]=now;clock.take(now);clock.complete(now);set(old,"taps",1L);call(old,"checkpoint",true);AutomationStore.save(c,true,Arrays.asList(step(8000)));TapService next=service();assertEquals(true,call(next,"startSession",true));assertEquals(1,((AutomationClock)get(next,"automation")).index);assertEquals(2,((AutomationClock)get(next,"automation")).actions.size());assertEquals(1L,get(next,"taps"));}
 @Test public void unfinishedActionRecoversPausedAtSameStep()throws Exception{AutomationClock clock=new AutomationClock(Arrays.asList(step(1000),step(3000)),true,false,0);clock.take(1000);String saved=new SessionCheckpoint("timeline",0,0,false,true,Collections.emptySet(),clock).encode(1001);c.getSharedPreferences("config",0).edit().putBoolean("sessionActive",true).putBoolean("detailedLauncher",false).putString("sessionCheckpoint",saved).commit();TapService next=service();call(next,"startSession",true);assertTrue(((SessionPause)get(next,"pause")).manual);assertEquals(0,((AutomationClock)get(next,"automation")).index);assertEquals(-1,((AutomationClock)get(next,"automation")).pending);assertTrue(((String)get(next,"recoveryNotice")).contains("unknown"));assertEquals(true,get(next,"panelDetailed"));}
 @Test public void generalTimersKeepIndependentRemainingIntervals()throws Exception{AutomationClock clock=new AutomationClock(Arrays.asList(step(1000),step(3000)),false,false,0);clock.take(1000);clock.complete(1100);SessionCheckpoint s=SessionCheckpoint.decode(new SessionCheckpoint("general",1,0,false,false,Collections.emptySet(),clock).encode(1500),100000);assertEquals(600,s.clock.remaining(100000));assertEquals(1500,s.clock.due[1]-100000);}
 @Test public void targetRefreshDoesNotRearmUnchangedTarget()throws Exception{Bitmap b=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);File f=TargetStore.save(c,b);TapService s=service();s.startSession();((boolean[])get(s,"latched"))[0]=true;set(s,"taps",9L);File second=TargetStore.save(c,b);s.refreshTargets();List<File> order=TargetStore.allActiveFiles(c);assertTrue(((boolean[])get(s,"latched"))[order.indexOf(f)]);assertFalse(((boolean[])get(s,"latched"))[order.indexOf(second)]);assertEquals(9L,get(s,"taps"));b.recycle();}
 @Test public void stopCannotBeResurrectedAndExplicitRestartResetsCount()throws Exception{TapService s=service();s.startSession();set(s,"taps",7L);call(s,"checkpoint",true);assertTrue(s.startSession());assertEquals(0L,get(s,"taps"));s.stopSession("Stop");assertFalse(c.getSharedPreferences("config",0).contains("sessionCheckpoint"));TapService next=service();next.onServiceConnected();assertFalse((Boolean)get(next,"running"));}
 @Test public void corruptCheckpointRecoversPausedRatherThanAutoReplay()throws Exception{TapService s=service();c.getSharedPreferences("config",0).edit().putString("sessionCheckpoint","bad data").commit();call(s,"startSession",true);assertTrue(((SessionPause)get(s,"pause")).manual);assertTrue(((String)get(s,"recoveryNotice")).contains("unavailable"));}
 @Test public void manualPauseFreezesRestoredTimeline()throws Exception{AutomationClock clock=new AutomationClock(Arrays.asList(step(3000)),true,false,0);clock.pause(1000);SessionCheckpoint s=SessionCheckpoint.decode(new SessionCheckpoint("timeline",0,0,true,false,Collections.emptySet(),clock).encode(9000),100000);assertEquals(-1,s.clock.take(200000));s.clock.resume(200000);assertEquals(2000,s.clock.remaining(200000));}
}
